"""Level 1: core SQL pattern catalog. Emitted to js/data_patterns.js by build_bank.py.
Templates use real Northwind identifiers (MySQL backtick quoting)."""

P = lambda id, name, problem, template, tables, columns, explanation, mistakes, not_when, tags: dict(
    id=id, name=name, problem=problem, template=template.strip(), tables=tables, columns=columns,
    explanation=explanation, mistakes=mistakes, notWhen=not_when, tags=tags)

PATTERNS = [
 P('select_filter', 'Basic SELECT and filtering', 'List rows/columns that satisfy simple conditions.',
   "SELECT `Company`, `City`\nFROM customers\nWHERE `State/Province` = 'WA'\n  AND `City` <> 'Seattle';",
   ['customers'], ['customers.Company', 'customers.City', 'customers.State/Province'],
   'WHERE filters rows before any grouping. Quote identifiers that contain spaces or "/" with backticks; string literals use single quotes.',
   ['Using double quotes for strings (MySQL may read them as identifiers in ANSI mode).', 'Forgetting backticks around `Last Name`.', 'Using = NULL instead of IS NULL.'],
   ['When the condition needs an aggregate: use HAVING.'], ['where', 'filter', 'select']),
 P('order_limit', 'ORDER BY and LIMIT', 'Sort the result and keep only the first rows.',
   "SELECT *\nFROM products\nORDER BY `List Price` DESC, ID\nLIMIT 5;",
   ['products'], ['products.List Price'],
   'ORDER BY sorts, LIMIT cuts after sorting. Add a tie-breaker column so the output is deterministic.',
   ['LIMIT without ORDER BY gives arbitrary rows.', 'Ties at the cut-off are silently dropped.', 'Writing ORDER BY a DESC, b when both must be DESC.'],
   ['When ties must all be returned: use a subquery on the threshold value or RANK()/DENSE_RANK().'], ['order by', 'limit', 'top n', 'sort']),
 P('distinct', 'DISTINCT / unique values', 'Return each value only once.',
   "SELECT DISTINCT `Ship Country/Region`\nFROM orders;",
   ['orders'], ['orders.Ship Country/Region'],
   'DISTINCT removes duplicate result rows (whole row, not first column). COUNT(DISTINCT x) counts different values of x.',
   ['Believing DISTINCT applies to only the first selected column.', 'Using DISTINCT to hide a wrong join that multiplies rows.', 'COUNT(DISTINCT a, b) is not the same as two separate counts.'],
   ['When per-group aggregates are also needed: use GROUP BY.'], ['distinct', 'unique', 'duplicates']),
 P('aggregate', 'Aggregate functions', 'COUNT / SUM / AVG / MIN / MAX over a set of rows.',
   "SELECT COUNT(*) AS n, AVG(`Shipping Fee`) AS avg_fee, MAX(`Shipping Fee`) AS max_fee\nFROM orders\nWHERE `Ship Country/Region` = 'USA';",
   ['orders'], ['orders.Shipping Fee', 'orders.Ship Country/Region'],
   'Aggregates collapse rows into one value; NULLs are ignored by every aggregate except COUNT(*).',
   ['COUNT(*) vs COUNT(col): the latter skips NULLs.', 'AVG over a column with NULLs ignores them (not treated as 0).', 'Mixing non-aggregated columns without GROUP BY.'],
   ['When a value per group is needed: add GROUP BY.'], ['count', 'sum', 'avg', 'min', 'max', 'aggregate']),
 P('group_having', 'GROUP BY and HAVING', 'Aggregate per group and filter on the aggregate.',
   "SELECT `Customer ID`, COUNT(*) AS n_orders\nFROM orders\nGROUP BY `Customer ID`\nHAVING COUNT(*) > 2;",
   ['orders'], ['orders.Customer ID'],
   'GROUP BY forms groups; HAVING filters groups after aggregation (WHERE filters rows before). More than N => > N, at least N => >= N.',
   ['Putting an aggregate in WHERE.', '> vs >= (more than vs at least).', 'Grouping by a name that is not unique (group by the ID too).', 'Selecting columns that are not in GROUP BY.'],
   ['When filtering on a plain column: use WHERE (cheaper).'], ['group by', 'having', 'per group', 'each']),
 P('inner_join', 'INNER JOIN', 'Combine rows from related tables; only matching rows survive.',
   "SELECT o.`Order ID`, c.`Company`\nFROM orders AS o\nJOIN customers AS c ON c.ID = o.`Customer ID`;",
   ['orders', 'customers'], ['orders.Customer ID', 'customers.ID'],
   'JOIN ... ON links the foreign key to the primary key. Rows without a partner are dropped.',
   ['Missing ON clause (cartesian product).', 'Joining on the wrong key (the dump declares no FK constraints).', 'Fan-out: joining one-to-many then summing a parent column.'],
   ['When unmatched rows must be kept: LEFT JOIN.'], ['join', 'inner join']),
 P('left_join', 'LEFT JOIN (keep unmatched)', 'Keep all rows of the left table even without a match.',
   "SELECT c.ID, c.`Company`, COUNT(o.`Order ID`) AS n_orders\nFROM customers AS c\nLEFT JOIN orders AS o ON o.`Customer ID` = c.ID\nGROUP BY c.ID, c.`Company`;",
   ['customers', 'orders'], ['customers.ID', 'orders.Customer ID'],
   'Unmatched left rows get NULLs on the right. COUNT(right.key) gives 0 for them; COUNT(*) would give 1.',
   ['Filtering the right table in WHERE turns the LEFT JOIN into an INNER JOIN (put the condition in ON).', 'COUNT(*) instead of COUNT(right.col).'],
   ['When only matching rows are wanted: INNER JOIN.'], ['left join', 'outer join', 'including those without']),
 P('subquery', 'Subquery (scalar / derived table)', 'Use the result of one query inside another.',
   "SELECT *\nFROM products\nWHERE `List Price` > (SELECT AVG(`List Price`) FROM products);",
   ['products'], ['products.List Price'],
   'A scalar subquery returns one value; a derived table in FROM needs an alias.',
   ['Scalar subquery returning more than one row (error).', 'Missing alias on derived table.'],
   ['When it can be a plain join without losing clarity.'], ['subquery', 'nested', 'derived table']),
 P('exists', 'EXISTS', 'Keep rows for which a related row exists.',
   "SELECT c.*\nFROM customers AS c\nWHERE EXISTS (SELECT 1 FROM orders AS o WHERE o.`Customer ID` = c.ID);",
   ['customers', 'orders'], ['customers.ID', 'orders.Customer ID'],
   'EXISTS stops at the first match and is NULL-safe; no duplicates from the outer table.',
   ['Forgetting the correlation condition (EXISTS always true).'], ['When you need columns from the inner table: JOIN.'], ['exists', 'semi join']),
 P('not_exists', 'NOT EXISTS / anti-join', 'Keep rows with NO related row.',
   "SELECT c.*\nFROM customers AS c\nWHERE NOT EXISTS (SELECT 1 FROM orders AS o WHERE o.`Customer ID` = c.ID);",
   ['customers', 'orders'], ['customers.ID', 'orders.Customer ID'],
   'NOT EXISTS is the safe anti-join. Equivalent: LEFT JOIN ... WHERE right.key IS NULL.',
   ['NOT IN with a subquery that returns NULL gives an empty result.', 'Inner join + <> does NOT express "never".'],
   [], ['not exists', 'never', 'without', 'no orders', 'anti join']),
 P('in_notin', 'IN / NOT IN', 'Membership test against a list or subquery.',
   "SELECT *\nFROM products\nWHERE ID IN (SELECT `Product ID` FROM `order details`);",
   ['products', 'order details'], ['products.ID', 'order details.Product ID'],
   'IN tests against a set. NOT IN is dangerous when the set contains NULL (comparison becomes UNKNOWN for every row).',
   ['NOT IN + NULL in subquery => no rows.', 'Large IN-lists are slow compared with a join.'],
   ['Negation with nullable columns: use NOT EXISTS.'], ['in', 'not in']),
 P('correlated', 'Correlated subquery', 'Inner query references the outer row.',
   "SELECT p.*\nFROM products AS p\nWHERE p.`List Price` > (SELECT AVG(q.`List Price`) FROM products AS q WHERE q.Category = p.Category);",
   ['products'], ['products.List Price', 'products.Category'],
   'The inner query runs per outer row (logically). Typical for "greater than the average of its own group".',
   ['Using the same alias in both levels.', 'Forgetting the correlation => global average.'],
   ['Big tables: a window function or a join to a grouped derived table is usually faster.'], ['correlated', 'compared to its own group']),
 P('self_join', 'SELF JOIN', 'Join a table to itself to compare rows or form pairs.',
   "SELECT a.`Product ID` AS p1, b.`Product ID` AS p2, COUNT(*) AS together\nFROM `order details` AS a\nJOIN `order details` AS b ON a.`Order ID` = b.`Order ID` AND a.`Product ID` < b.`Product ID`\nGROUP BY a.`Product ID`, b.`Product ID`\nORDER BY together DESC;",
   ['order details'], ['order details.Order ID', 'order details.Product ID'],
   'Two aliases of one table. Use < (not <>) on the key so each unordered pair appears once and no row pairs with itself.',
   ['<> returns each pair twice.', 'Missing the self-pair exclusion.'], [], ['self join', 'pairs', 'together', 'same']),
 P('cond_agg', 'Conditional aggregation', 'Several filtered aggregates in one pass (pivot-like).',
   "SELECT `Employee ID`,\n       SUM(CASE WHEN `Shipped Date` IS NULL THEN 1 ELSE 0 END) AS not_shipped,\n       SUM(CASE WHEN `Shipped Date` IS NOT NULL THEN 1 ELSE 0 END) AS shipped\nFROM orders\nGROUP BY `Employee ID`;",
   ['orders'], ['orders.Employee ID', 'orders.Shipped Date'],
   'SUM(CASE WHEN cond THEN x ELSE 0 END) or COUNT(CASE WHEN cond THEN 1 END) counts/sums only matching rows per group.',
   ['COUNT(CASE ... ELSE 0 END) counts every row (0 is not NULL).', 'Using WHERE would filter away the other categories.'],
   [], ['case when', 'conditional', 'pivot', 'breakdown']),
 P('date', 'Date manipulation', 'Filter or group by year/month/day.',
   "SELECT DATE_FORMAT(`Order Date`, '%Y-%m') AS ym, COUNT(*) AS n\nFROM orders\nWHERE `Order Date` >= '2006-01-01' AND `Order Date` < '2007-01-01'\nGROUP BY ym;",
   ['orders'], ['orders.Order Date'],
   'Prefer a half-open range (>= start AND < next start) over YEAR(col)=2006: it can use an index. DATE_FORMAT builds YYYY-MM keys.',
   ['BETWEEN with datetime misses the last day after 00:00:00.', 'Functions on the column disable index use.', 'Mixing %m (month) and %i (minute) in DATE_FORMAT.'],
   [], ['date', 'month', 'year', 'between']),
 P('topn_rank', 'Ranking and Top-N (incl. Nth)', 'Top N rows, Nth highest, ranking with or without ties.',
   "SELECT *\nFROM orders\nORDER BY `Shipping Fee` DESC, `Order ID`\nLIMIT 3 OFFSET 5;  -- 6th..8th row\n\n-- ties-aware: DENSE_RANK() OVER (ORDER BY `Shipping Fee` DESC) BETWEEN 6 AND 8",
   ['orders'], ['orders.Shipping Fee'],
   'LIMIT/OFFSET ranks by ROW position; RANK/DENSE_RANK rank by VALUE and treat equal values as tied. Decide which one the question means.',
   ['OFFSET is 0-based: 6th row => OFFSET 5.', 'Ignoring ties.', 'Nth highest value vs Nth row.'],
   [], ['top', 'rank', 'nth', 'highest', 'offset']),
 P('multi_agg', 'Multiple-table aggregation', 'Join several tables then aggregate.',
   "SELECT c.ID, c.`Company`, SUM(od.`Unit Price` * od.Quantity) AS total\nFROM customers AS c\nJOIN orders AS o ON o.`Customer ID` = c.ID\nJOIN `order details` AS od ON od.`Order ID` = o.`Order ID`\nGROUP BY c.ID, c.`Company`;",
   ['customers', 'orders', 'order details'], ['customers.ID', 'orders.Customer ID', 'order details.Order ID'],
   'Follow the key chain customers -> orders -> order details -> products. Aggregate at the end, group by the entity key.',
   ['Summing an orders column after joining order details (fan-out, double counting).', 'Grouping by name only.'],
   [], ['join', 'aggregate', 'total', 'per customer']),
 P('optimization', 'Query optimization', 'Make a query use indexes and read less data.',
   "-- non-sargable\nSELECT * FROM orders WHERE YEAR(`Order Date`) = 2006;\n-- sargable + only needed columns\nSELECT `Order ID`, `Customer ID`, `Order Date`\nFROM orders\nWHERE `Order Date` >= '2006-01-01' AND `Order Date` < '2007-01-01';\n-- and CREATE INDEX idx_orders_date ON orders (`Order Date`);",
   ['orders'], ['orders.Order Date'],
   'Avoid SELECT *, avoid functions on indexed columns, filter early, index filter/join/sort columns, check with EXPLAIN.',
   ['Index on a column wrapped in a function is unused.', 'Leading-wildcard LIKE is not index-friendly.'],
   [], ['index', 'performance', 'efficient', 'explain', 'select *']),
 P('null_handling', 'NULL handling', 'Missing values in filters, aggregates and comparisons.',
   "SELECT COUNT(*) AS all_rows, COUNT(`Payment Type`) AS with_type,\n       SUM(`Payment Type` IS NULL) AS missing\nFROM orders;",
   ['orders'], ['orders.Payment Type'],
   'NULL = anything is UNKNOWN. Use IS NULL / IS NOT NULL, COALESCE for defaults; aggregates skip NULLs.',
   ['col = NULL never matches.', '<> excludes NULL rows silently.', 'NOT IN with NULL.'],
   [], ['null', 'missing', 'coalesce', 'is null']),
 P('division', 'Relational division', 'Entities related to ALL members of a set.',
   "SELECT o.`Customer ID`\nFROM orders AS o\nJOIN `order details` AS od ON od.`Order ID` = o.`Order ID`\nJOIN products AS p ON p.ID = od.`Product ID`\nWHERE p.Category = 'Beverages'\nGROUP BY o.`Customer ID`\nHAVING COUNT(DISTINCT p.ID) = (SELECT COUNT(*) FROM products WHERE Category = 'Beverages');",
   ['orders', 'order details', 'products'], ['orders.Customer ID', 'products.Category'],
   'Count the distinct members each entity covers and compare with the total number of members. Alternative: double NOT EXISTS.',
   ['COUNT without DISTINCT.', 'Comparing against a count that was not restricted to the same subset.'],
   [], ['all', 'every', 'division']),
 P('computed', 'Computed columns and ratios', 'Derived expressions, ratios, rounding, percentages.',
   "SELECT `Product Name`, ROUND((`List Price` - `Standard Cost`) / `Standard Cost`, 4) AS `Profit Margin`\nFROM products\nWHERE (`List Price` - `Standard Cost`) / `Standard Cost` >= 0.5;",
   ['products'], ['products.List Price', 'products.Standard Cost'],
   'Column aliases cannot be used in WHERE; repeat the expression or use HAVING / a derived table. 50% => 0.5.',
   ['Alias in WHERE.', 'Percent written as 50 instead of 0.5.', 'Division by zero yields NULL in MySQL.'],
   [], ['ratio', 'percent', 'margin', 'round']),
 P('all_any', 'ALL / ANY comparison', 'Compare with every / at least one value of a subquery.',
   "SELECT * FROM products\nWHERE `List Price` > ALL (SELECT `List Price` FROM products WHERE Category = 'Beverages');",
   ['products'], ['products.List Price', 'products.Category'],
   '> ALL = greater than the maximum; > ANY = greater than the minimum. Equivalent to comparing with MAX()/MIN().',
   ['Mixing up ALL and ANY.', 'ALL over an empty set is true.'],
   [], ['all', 'any', 'some']),
 P('set_ops', 'UNION / UNION ALL', 'Stack results of several queries.',
   "SELECT `Company` FROM customers\nUNION\nSELECT `Company` FROM suppliers;",
   ['customers', 'suppliers'], ['customers.Company', 'suppliers.Company'],
   'UNION removes duplicates (extra sort/dedup); UNION ALL keeps all rows and is faster. Column counts and types must match.',
   ['UNION when duplicates are wanted.', 'Different column order between branches.'],
   [], ['union', 'combine']),
 P('string_funcs', 'String functions', 'Build or split text: CONCAT, UPPER, REPLACE, SUBSTRING_INDEX, LIKE.',
   "SELECT CONCAT(`First Name`, ' ', UPPER(`Last Name`)) AS full_name,\n       SUBSTRING_INDEX(`E-mail Address`, '@', -1) AS domain,\n       REPLACE(`Job Title`, 'Sales ', '') AS short_title\nFROM employees;",
   ['employees'], ['employees.First Name', 'employees.Last Name', 'employees.E-mail Address'],
   'CONCAT returns NULL if any argument is NULL (CONCAT_WS skips NULLs). SUBSTRING_INDEX(s, sep, n): n>0 text before the nth separator, n<0 text after the nth separator from the right. LENGTH counts bytes, CHAR_LENGTH counts characters.',
   ['Forgetting the space/trailing separator in REPLACE.', 'LENGTH vs CHAR_LENGTH.', 'LIKE wildcards: % any string, _ one character.'],
   [], ['concat', 'upper', 'lower', 'replace', 'substring', 'like', 'string']),
]
